class Solution:
    def romanToInt(self, s: str) -> int:
        values = {"I": 1, "V": 5, "X": 10, "L": 50,
                  "C": 100, "D": 500, "M": 1000}
        total = largest = 0
        for char in reversed(s):
            value = values[char]
            if value < largest:
                total -= value
            else:
                total += value
                largest = value
        return total
